<style>.media-head{display:flex;justify-content:space-between;gap:18px;align-items:flex-start;margin-bottom:20px}.media-upload{display:flex;gap:10px;align-items:end}.media-upload label{font-weight:700}.media-upload input{max-width:360px}.media-filters{display:grid;grid-template-columns:minmax(220px,1fr) 190px auto;gap:10px;margin:18px 0}.media-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(210px,1fr));gap:16px}.media-card{background:#fff;border:1px solid var(--line);border-radius:13px;overflow:hidden;min-width:0}.media-preview{height:150px;background:#eef3f7;display:grid;place-items:center;overflow:hidden}.media-preview img{width:100%;height:100%;object-fit:contain}.media-pdf{font-size:42px;color:#b42318}.media-body{padding:14px}.media-body h2{font-size:15px;margin:0 0 6px;overflow-wrap:anywhere}.media-meta{font-size:12px;color:var(--muted);margin-bottom:11px}.media-actions{display:grid;gap:8px}.media-actions summary{cursor:pointer;color:var(--blue);font-weight:700}.media-actions form{display:grid;gap:7px;padding-top:8px}.media-actions .danger{background:#fff;color:#991b1b;border:1px solid #f3b4b4}.notice{background:#dcfce7;color:#166534;padding:11px 13px;border-radius:9px;margin-bottom:14px}.pagination{display:flex;justify-content:center;gap:7px;margin-top:24px}.pagination a{padding:8px 11px;border:1px solid var(--line);background:#fff;border-radius:8px;text-decoration:none;color:var(--text)}@media(max-width:760px){.media-head,.media-upload{display:grid}.media-filters{grid-template-columns:1fr}.media-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:480px){.media-grid{grid-template-columns:1fr}}</style>
